        for (size_t k = 0; k < n; ++k) {
            const double a_val = A[i * n + k];
            if (a_val >= -100.0 && a_val <= 100.0) {
                const double* b_row = B + k * p;
                for (size_t j = 0; j < p; ++j) {
                    const double b_val = b_row[j];
                    if (b_val >= -100.0 && b_val <= 100.0) {
                        c_row[j] += a_val * b_val;
                    }
                }
            }
        }
    }
}

