void matrix_normalize_rows(float* mat, size_t m, size_t n) {
    for (size_t i = 0; i < m; ++i) {
        float* row = mat + i * n;
        float norm = 0.0f;
        for (size_t j = 0; j < n; ++j) {
            norm += row[j] * row[j];
        }
        norm = sqrtf(norm);
        if (norm > 1e-8f) {
            const float inv = 1.0f / norm;
            for (size_t j = 0; j < n; ++j) {
                row[j] *= inv;
            }
        }
    }
}

