        bool ascending = directions[i];
        for (size_t j = 1; j < cols; j++) {
            int curr = matrix[i * cols + j];
            int prev = matrix[i * cols + (j - 1)];
            if ((ascending && curr < prev) || (!ascending && curr > prev)) {
                return false;
            }
        }
    }
    return true;
}

