MinMaxPair min_max_pair(const int16_t* vec, size_t length) {
    MinMaxPair result;
    if (length == 0 || vec == NULL) {
        result.min_num = 0;
        result.max_num = 0;
        return result;
    }

    int16_t min_val = vec[0];
    int16_t max_val = vec[0];
    for (size_t i = 1; i < length; ++i) {
        min_val = std::min(vec[i], min_val);
        max_val = std::max(vec[i], max_val);
    }

    result.min_num = min_val;
    result.max_num = max_val;
    return result;
}

bool matrix_rows_strictly_increasing(const int* matrix, size_t rows, size_t cols) {
    if (matrix == NULL || rows <= 0 || cols <= 0) {
        return false;
    }
    const size_t length = rows * cols;
    size_t k = 1;
    for (; k < length; ++k) {
        if (matrix[k] <= matrix[k - 1]) {
            break;
        }
    }
    if (k == length) {
        return true;
    }
    const int* row = matrix;
    for (size_t i = 0; i < rows; ++i, row += cols) {
        int prev = row[0];
        for (size_t j = 1; j < cols; ++j) {
            const int cur = row[j];
            if (cur <= prev) {
                return false;
            }
            prev = cur;
        }
    }
    return true;
}

bool matrix_blocks_equal(const int* matrix, size_t block_size, size_t rows, size_t cols) {
    if (matrix == NULL || block_size == 0) {
        return false;
    }
    if (rows % block_size != 0 || cols % block_size != 0) {
        return false;
    }
    const size_t block_rows = rows / block_size;
    const size_t block_cols = cols / block_size;
    for (size_t br = 0; br < block_rows; ++br) {
        for (size_t bc = (br == 0 ? 1 : 0); bc < block_cols; ++bc) {
            for (size_t r = 0; r < block_size; ++r) {
                const int* ref = matrix + r * cols;
                const int* cur = matrix + (br * block_size + r) * cols + bc * block_size;
                for (size_t c = 0; c < block_size; ++c) {
                    if (ref[c] != cur[c]) {
                        return false;
                    }
                }
            }
        }
    }
    return true;
}

bool vector_block_equal(const double* vec, double tolerance, size_t length, size_t block_size) {
    if (vec == NULL || block_size == 0 || length < block_size) {
        return false;
    }

    const size_t num_blocks = length / block_size;
    for (size_t block = 1; block < num_blocks; ++block) {
        const double* cur = vec + block * block_size;
        for (size_t j = 0; j < block_size; ++j) {
            if (fabs(cur[j] - vec[j]) > tolerance) {
                return false;
            }
        }
    }
    return true;
}

