void tensor_three_valued_logic(const int8_t* A, const int8_t* B, int8_t* C, size_t length) {
    for (size_t idx = 0; idx < length; ++idx) {
        int a = A[idx], b = B[idx];
        if (a == 0 || b == 0) {
            C[idx] = 0;
        } else if (a > 0 && b > 0) {
            C[idx] = 1;
        } else if (a < 0 && b < 0) {
            C[idx] = -1;
        } else {
            C[idx] = 0;
        }
    }
}

void tensor_bit_op(const uint16_t* A, const uint16_t* B, uint16_t* C, size_t length) {
    if (length == 0) {
        return;
    }
    const size_t half = length / 2;
    const size_t xor_end = (length + 1) / 2;
    for (size_t idx = 0; idx < xor_end; ++idx) {
        C[idx] = A[idx] ^ B[idx];
    }
    if ((length & 1u) == 0u) {
        C[half] = A[half];
        for (size_t idx = half + 1; idx < length; ++idx) {
            C[idx] = A[idx] & B[idx];
        }
    } else {
        for (size_t idx = xor_end; idx < length; ++idx) {
            C[idx] = A[idx] & B[idx];
        }
    }
}

void tensor_multi_select(const float* A, const float* B, const float* C, const float* D, const bool* cond1, const bool* cond2, float* out, size_t dim1, size_t dim2, size_t dim3) {
    const size_t total = dim1 * dim2 * dim3;
    for (size_t idx = 0; idx < total; ++idx) {
        if (cond1[idx]) {
            out[idx] = cond2[idx] ? A[idx] : B[idx];
        } else {
            out[idx] = cond2[idx] ? C[idx] : D[idx];
        }
    }
}

void tensor_bit_count(const uint32_t* A, uint8_t* out, size_t dim1, size_t dim2, size_t dim3) {
