void matrix_conditional_bit_rotate(const uint32_t* src, uint32_t* dst, uint8_t rotate_bits, size_t length) {
    uint32_t r = ((uint32_t)rotate_bits) & 31u;
    for (size_t idx = 0; idx < length; ++idx) {
        uint32_t val = src[idx];
        if ((val & 0xFu) == 0xFu) {
            dst[idx] = (r == 0u) ? val : ((val >> r) | (val << (32u - r)));
        } else {
            dst[idx] = ~val;
        }
    }
}

inline __attribute__((always_inline,hot)) void tensor_ternary_compare(const float* A, const float* B, int8_t* out, float epsilon, size_t length) {
    float eps = (epsilon < 0.0f) ? -epsilon : epsilon;
    for (size_t idx = 0; idx < length; ++idx) {
        float diff = A[idx] - B[idx];
        if (diff > eps) out[idx] = 1;
        else if (diff < -eps) out[idx] = -1;
        else out[idx] = 0;
    }
}

void float_to_int_saturate(const float* A, int32_t* B, size_t size) {
