std::vector<int> even_odd_palindrome(int n) {
    int num1 = 0;
    int num2 = 0;
    for (int i = 1; i <= n; ++i) {
        int x = i;
        int rev = 0;
        while (x > 0) {
            rev = rev * 10 + x % 10;
            x /= 10;
        }
        if (rev == i) {
            if (i % 2 == 1) {
                num1 += 1;
            } else {
                num2 += 1;
            }
        }
    }
    return {num2, num1};
}

int count_nums(std::vector<int> n) {
    int num = 0;
    for (size_t i = 0; i < n.size(); ++i) {
        int value = n[i];
        if (value > 0) {
            ++num;
            continue;
        }
        int sum = 0;
        int w = std::abs(value);
        while (w >= 10) {
            sum += w % 10;
            w /= 10;
        }
        sum -= w;
        if (sum > 0) {
            ++num;
        }
    }
    return num;
}

