inline __attribute__((always_inline,hot)) std::vector<int> minPath(const std::vector<std::vector<int> > & grid, int k) {
    int n = grid.size();
    int x, y, minValue;

    // Find the position of the cell with value 1
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (grid[i][j] == 1) {
                x = i;
                y = j;
            }
        }
    }

    // Find the smallest neighbor of the cell containing 1
    minValue = INT_MAX;

    if (x > 0 && grid[x - 1][y] < minValue) {
        minValue = grid[x - 1][y];
    }
    if (x < n - 1 && grid[x + 1][y] < minValue) {
        minValue = grid[x + 1][y];
    }
    if (y > 0 && grid[x][y - 1] < minValue) {
        minValue = grid[x][y - 1];
    }
    if (y < n - 1 && grid[x][y + 1] < minValue) {
        minValue = grid[x][y + 1];
    }

    // Pre-allocate the output vector and directly assign values
    std::vector<int> out(k);
    for (int i = 0; i < k; i++) {
        if (i % 2 == 0) {
            out[i] = 1;
        } else {
            out[i] = minValue;
        }
    }

    return out;
}

uint64_t digits(uint64_t n) {
    uint64_t prod = 1;
    uint64_t has = 0;
    if (n == 0) {
        return 0;
    }
    while (n > 0) {
        const uint64_t digit = n % 10;
        if (digit % 2 == 1) {
            has = 1;
            prod *= digit;
        }
        n /= 10;
    }
    return has ? prod : 0;
}

