uint64_t get_max_triples(uint64_t n) {
    const uint64_t count_zero = (n + 1) / 3;
    const uint64_t count_one = n - count_zero;
    const uint64_t triples_zero = count_zero >= 3 ? count_zero * (count_zero - 1) * (count_zero - 2) / 6 : 0;
    const uint64_t triples_one = count_one >= 3 ? count_one * (count_one - 1) * (count_one - 2) / 6 : 0;
    return triples_zero + triples_one;
}

int x_or_y(int n, int x, int y) {
    if (n < 2) {
        return y;
    }
    if (n == 2) {
        return x;
    }
    if ((n & 1) == 0) {
        return y;
    }
    for (int i = 3; i * i <= n; i += 2) {
        if (n % i == 0) {
            return y;
        }
    }
    return x;
}

uint64_t double_the_difference(const std::vector<float> & lst) {
    uint64_t sum = 0;
    for (size_t i = 0; i < lst.size(); ++i) {
        const float rounded = roundf(lst[i]);
        if (fabsf(lst[i] - rounded) < 1e-4f && rounded > 0.0f) {
            const int value = (int)rounded;
            if ((value & 1) == 1) {
                sum += (uint64_t)(value * value);
            }
        }
    }
    return sum;
}

